import React, {useId} from 'react';
import './choice.css';
export type WorkspaceView = 'board' | 'list' | 'timeline';
export type ViewAction = {type: 'workspace/viewChanged'; view: WorkspaceView};
export function WorkspaceViewChoice({value, dispatch}: {value: WorkspaceView; dispatch: (action: ViewAction) => void}) {
 const id = useId();
 return <fieldset className="view-choice"><legend>Workspace view</legend>{(['board', 'list', 'timeline'] as const).map(view => <label key={view}><input type="radio" name={id} value={view} checked={value === view} onChange={() => dispatch({type: 'workspace/viewChanged', view})}/><span>{view[0].toUpperCase() + view.slice(1)}</span></label>)}</fieldset>;
}
